import{_ as t,o as i,c as r,ab as l}from"./chunks/framework.DQy4ijAa.js";const a="/hubHooks/assets/image-20251119144117870.B8-crOU9.png",o="/hubHooks/assets/image-20251120145703914.DbXPzAK3.png",C=JSON.parse('{"title":"WebRTC优势","description":"","frontmatter":{},"headers":[],"relativePath":"front/realtime-media/webRTC.md","filePath":"front/realtime-media/webRTC.md","lastUpdated":1773021383000}'),n={name:"front/realtime-media/webRTC.md"};function s(p,e,b,g,c,T){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="webrtc优势" tabindex="-1">WebRTC优势 <a class="header-anchor" href="#webrtc优势" aria-label="Permalink to &quot;WebRTC优势&quot;">​</a></h1><ol><li><p>超低延迟（实时）：<strong>端到端 200ms 以内</strong>，这是 HLS / DASH 永远做不到的</p><ul><li>视频会议</li><li>在线课堂</li><li>远程协作</li><li>游戏语音</li></ul></li><li><p>浏览器直连（P2P 优先）</p><ul><li>延迟低</li><li>带宽压力小</li><li>成本低</li></ul></li><li><p>安全 ：WebRTC <strong>强制加密</strong>：</p><ul><li>信令：HTTPS / WSS</li><li>媒体： <ul><li>DTLS</li><li>SRTP</li></ul></li></ul></li><li><p>WebRTC 其实是一个 <strong>通用的低延迟通信框架</strong></p><p>WebRTC ≠ 视频通话 它还提供：</p><ul><li><strong>RTCDataChannel</strong><ul><li>文本</li><li>二进制</li><li>文件</li><li>游戏状态同步</li></ul></li></ul></li></ol><h1 id="webrtc架构" tabindex="-1">WebRTC架构 <a class="header-anchor" href="#webrtc架构" aria-label="Permalink to &quot;WebRTC架构&quot;">​</a></h1><p>下面这张图来自<a href="https://webrtc.github.io/webrtc-org/architecture/" target="_blank" rel="noreferrer">WebRTC官网</a></p><p><img src="'+a+'" alt="image-20251119144117870"></p><p>总的来说大致可以分为<strong>四个层次：接口层、会话层、核心引擎层和设备层</strong></p><p><strong>接口层</strong></p><p>接口层是WebRTC架构的最上层，主要包括Web的接口层和C++的接口层。Web的接口层主要供开发者调用，通过JavaScript API实现WebRTC功能。在这层中开发者无需关心复杂的底层技术，只需了解webRTC的大致流程原理，调其API即可利用WebRTC实现点对点的通讯功能。</p><p>C++的接口层则提供了对底层硬件和操作系统的直接访问，实现了更高效的性能。主要是<strong>供浏览器支持WebRTC规范而调用的API</strong> 。这一层的主要作用就是把WebRTC的核心功能暴露出来，如设备管理，音视频流数据采集等，方便浏览器厂商开发处理。</p><p><strong>会话层</strong></p><p><code>Session management / Abstract signaling (Session)</code>标注的一层就是会话管理层。这一层提供了会话功能管理功能，可进行创建会话、管理会话、管理上下文环境等。而这一层又会涉及到各种协议。</p><p><strong>引擎层</strong></p><p>这一层为WebRTC核心层中最重、最复杂的一层。而这一层又分为三个小模块，分别是：Voice Engine（音频引擎）、Video Engine（视频引擎）以及Transport（传输模块）。</p><p>Voice Engine是一个包含了系列音频处理功能的框架，如音频采集、音频编解码、音频优化（包括降噪、回声消除等）等一系列的音频功能。</p><p>Video Engine是一个包含了系列视频处理功能的框架，如视频采集、视频编解码、根据网络抖动动态修改视频传输质量、图像处理等。</p><p>Transport(传输模块)，在WebRTC中，数据传输除了音视频等流媒体数据之外，还可以传输文件、文本、图片等其他二进制数据，这些功能就是这个模块所提供的。</p><p>这四层中，最复杂最核心的当然就是第三层的引擎层。其中音频引擎与视频引擎是相对比较独立的，但他们都需要与网络传世层(transport) 打交道。也就是说，他们都需要将自己产生的数据通过网络传输层发送出去；同时，也需要通过网络传输层接收其他端发过来的数据。此外，音频引擎与视频引擎由于需要进行音视频同步，所以他们之间也存在关联关系。</p><p><img src="'+o+'" alt="image-20251120145703914"></p><p><strong>设备层</strong></p><p>设备层是WebRTC架构的最底层，主要负责音视频的采集和渲染，以及底层的网络传输。设备层需要与操作系统和硬件进行交互，实现音视频数据的采集和渲染，同时还需要处理网络数据的发送和接收。</p>',20)])])}const d=t(n,[["render",s]]);export{C as __pageData,d as default};
